(function () {'use strict';var form = document.getElementById('reg-form');if (!form || !window.ZamoveValidation) return;var V = window.ZamoveValidation;var ENDPOINT = 'api/auth/register.php';var TIMEOUT_MS = 15000;var FIELDS = ['role', 'full_name', 'email', 'phone', 'password'];var statusBox = document.getElementById('reg-status');var submitBtn = document.getElementById('reg-submit');var submitLabel = submitBtn.textContent;var touched = {};function input(name) { return form.elements[name]; }
function errBox(name) { return document.getElementById('reg-' + name + '-err'); }
function showFieldError(name, message) {var el = input(name), box = errBox(name);if (!el || !box) return;box.textContent = message;el.setAttribute('aria-invalid', 'true');el.classList.remove('ok');}
function showFieldOk(name) {var el = input(name), box = errBox(name);if (!el || !box) return;box.textContent = '';el.removeAttribute('aria-invalid');el.classList.add('ok');}
function clearFieldState(name) {var el = input(name), box = errBox(name);if (!el || !box) return;box.textContent = '';el.removeAttribute('aria-invalid');el.classList.remove('ok');}
function showStatus(kind, message, extraNode) {statusBox.className = 'alert ' + kind;statusBox.textContent = message;if (extraNode) statusBox.appendChild(extraNode);statusBox.classList.remove('hid');}
function hideStatus() {statusBox.className = 'alert hid';statusBox.textContent = '';}
function setLoading(on) {submitBtn.disabled = on;submitBtn.setAttribute('aria-busy', on ? 'true' : 'false');submitBtn.textContent = '';if (on) {var spin = document.createElement('span');spin.className = 'spin';spin.setAttribute('aria-hidden', 'true');submitBtn.appendChild(spin);submitBtn.appendChild(document.createTextNode('Creating account…'));} else {submitBtn.textContent = submitLabel;}
FIELDS.forEach(function (n) { input(n).readOnly = on; });}
function collect() {var data = {};FIELDS.forEach(function (n) { data[n] = V.normalise(n, input(n).value); });return data;}
function checkOne(name) {var msg = V.validateField(name, input(name).value);if (msg) showFieldError(name, msg); else showFieldOk(name);return msg;}
FIELDS.forEach(function (name) {var el = input(name);el.addEventListener('blur', function () { touched[name] = true; if (el.value !== '' || name === 'role') checkOne(name); });el.addEventListener('input', function () {if (touched[name]) checkOne(name);hideStatus();});el.addEventListener('change', function () { touched[name] = true; checkOne(name); });});form.addEventListener('submit', function (e) {e.preventDefault();hideStatus();var data = collect();var errors = V.validateAll(data);var names = Object.keys(errors);FIELDS.forEach(function (n) { touched[n] = true; if (errors[n]) showFieldError(n, errors[n]); else showFieldOk(n); });if (names.length) {showStatus('bad', 'Please fix ' + names.length + ' field' + (names.length > 1 ? 's' : '') + ' before continuing.');input(names[0]).focus();return;}
send(data);});function send(data) {setLoading(true);var controller = new AbortController();var timer = setTimeout(function () { controller.abort(); }, TIMEOUT_MS);fetch(ENDPOINT, {method: 'POST',headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, application/problem+json' },body: JSON.stringify(data),credentials: 'same-origin',signal: controller.signal
})
.then(function (res) {var type = res.headers.get('Content-Type') || '';var parse = type.indexOf('json') !== -1 ? res.json() : Promise.resolve(null);return parse.catch(function () { return null; }).then(function (payload) { return { res: res, payload: payload }; });})
.then(function (r) { handleResponse(r.res, r.payload); })
.catch(function (err) {showStatus('bad', err && err.name === 'AbortError'
? 'The server took too long to answer. Check your connection and try again.'
: 'Could not reach the server. Check your internet connection and try again.');})
.then(function () { clearTimeout(timer); setLoading(false); });}
function handleResponse(res, payload) {if (res.ok) {form.reset();FIELDS.forEach(function (n) { clearFieldState(n); touched[n] = false; });var go = document.createElement('button');go.type = 'button';go.className = 'btn s l';go.style.marginLeft = '12px';go.textContent = 'Go to log in';go.addEventListener('click', function () { document.querySelector('[data-tab=in]').click(); hideStatus(); });showStatus('ok', (payload && payload.message) || 'Account created.', go);return;}
if ((res.status === 422 || res.status === 409) && payload && Array.isArray(payload.errors)) {var first = null, unmatched = [];payload.errors.forEach(function (e) {if (e && FIELDS.indexOf(e.field) !== -1) {showFieldError(e.field, String(e.message || 'Invalid value.'));if (!first) first = e.field;} else if (e) {unmatched.push(String(e.message || 'Invalid request.'));}
});showStatus('bad', unmatched.length ? unmatched.join(' ') : (payload.detail || 'Please check the highlighted fields.'));if (first) input(first).focus();return;}
if (res.status >= 500) {showStatus('bad', 'Something went wrong on our side. Please try again in a few minutes.');return;}
showStatus('bad', (payload && payload.detail) || ('The request was rejected (error ' + res.status + ').'));}
})();